"""Assemble references.yaml and renumber citations. Run once from the app folder (2026-11-24)."""
import yaml, re, json, sys
C="content-pack/"; cand=yaml.safe_load(open(C+"references.candidates.yaml",encoding="utf-8"))["references"]; by={r["n"]:r for r in cand}
S={1:"Umbrella review of 24 systematic reviews of oral ginger; grades certainty by outcome with GRADE and AMSTAR-2.",2:"Overview of 27 systematic reviews of ginger for any condition, with quality appraisal.",3:"Systematic review of 109 randomised trials of ginger across all indications, with risk-of-bias assessment.",4:"Umbrella review of 36 publications of meta-analyses on ginger and metabolic and inflammatory measures.",5:"Systematic review of meta-analyses (2010–2025) on inflammation, type 2 diabetes, oxidative stress and pregnancy nausea.",6:"Evidence scan and umbrella review of ginger in pregnancy and lactation; seven meta-analyses of pregnancy nausea appraised.",7:"Comprehensive 2005 review of ginger's pharmacological and clinical effects, sceptical about most indications.",9:"Meta-analysis of twelve trials (1278 women) of oral ginger for nausea and vomiting of pregnancy, including safety outcomes.",10:"Randomised double-masked placebo-controlled trial of oral ginger in 70 women with nausea and vomiting of pregnancy.",13:"Multicentre double-blind trial of three ginger doses against placebo for chemotherapy-induced nausea; 576 patients analysed.",14:"Systematic review and subgroup meta-analysis of 23 trials of ginger for chemotherapy-induced nausea and vomiting.",15:"Two-centre double-blind placebo-controlled trial of a standardised ginger extract during chemotherapy in 103 adults.",16:"Review of proposed mechanisms by which ginger might act in chemotherapy-induced nausea and vomiting.",17:"Meta-analysis of five randomised trials (363 patients) of ginger for postoperative nausea and vomiting.",20:"Crossover placebo-controlled study of ginger in 13 volunteers with motion sickness induced by circular vection.",21:"Six-week multicentre placebo-controlled trial of a two-species ginger extract in 261 patients with knee osteoarthritis.",22:"Systematic review and meta-analysis of ginger for primary dysmenorrhoea; four placebo-controlled trials pooled.",23:"Systematic review and meta-analysis of ginger for pain in primary dysmenorrhoea; 12 studies pooled.",24:"Meta-analysis of ten trials (490 people) of ginger in type 2 diabetes and metabolic syndrome.",25:"Meta-analysis of ten trials of ginger supplementation on glycaemic, lipid and blood-pressure measures in type 2 diabetes.",26:"GRADE-assessed dose–response meta-analysis of 29 trials of ginger on inflammatory and antioxidant biomarkers.",27:"Double-blind placebo-controlled trial of ginger extract added to ketoprofen for acute migraine in 60 adults.",28:"Open-label three-way crossover study of ginkgo and ginger with warfarin in 12 healthy men.",29:"Review of the evidence to 1999 for interactions of warfarin with garlic, ginger, ginkgo and ginseng.",30:"Randomised double-blind crossover study of ginger on gastric emptying in 11 patients with functional dyspepsia.",31:"Randomised double-blind crossover study of ginger on gastric emptying and motility in 24 healthy volunteers.",32:"First human pharmacokinetic study of gingerols and 6-shogaol after single oral doses of ginger in 27 volunteers.",34:"Pharmacokinetics and metabolite profiling of gingerols and shogaols in asthma patients over 56 days of ginger extract.",35:"In vitro and mouse study of the solubility, metabolic stability and pharmacokinetics of ginger phenolics.",37:"Cell and human-tissue study showing non-competitive inhibition of human 5-HT3 receptors by ginger extracts and constituents.",38:"Isolated-tissue study of gingerols and 6-shogaol at guinea-pig M3 and 5-HT3 and rat 5-HT4 receptors.",39:"Structural modelling, electrophysiology and mutagenesis study of how ginger compounds activate the TRPV1 channel.",40:"Rat and cell study of gingerols and shogaols at TRPV1, identifying 10-shogaol as active but non-pungent.",41:"In vitro study of 20 ginger constituents and analogues as inhibitors of platelet activation and COX-1.",42:"Haplotype-resolved genome of the ginger cultivar 'Zhugen' with a proposed gingerol biosynthetic pathway.",43:"Haplotype-resolved diploid ginger genome on 11 pseudochromosome pairs, with allele-specific expression analysis.",44:"Genome of 'Small Laiwu Ginger' with evidence for transcriptional regulation of 6-gingerol biosynthesis.",45:"Enzyme-activity study of the phenylpropanoid pathway in ginger and turmeric tissues; identifies thioesterases in ginger.",46:"Reference transcriptome and gingerol quantification across ginger tissues and rhizome developmental stages.",47:"Identification and characterisation of mono- and sesquiterpene synthases from ginger and turmeric.",48:"Molecular phylogeny of the Zingiberaceae and a revised classification into four subfamilies.",49:"Comparative analysis of 14 chloroplast genomes of Zingiber species with a genus-level phylogeny.",50:"HPLC assay of gingerols and shogaols in fresh rhizomes of 17 Australian ginger clones, including tetraploids.",53:"Bioassay-guided isolation of antifungal compounds from an African land race of ginger.",54:"Study of root exudates and root-associated bacteria of ginger during Ralstonia solanacearum infection.",55:"Microbiome and metabolome comparison of healthy ginger plants and plants with rhizome rot.",56:"Review of Pythium soft rot of ginger: detection, identification and control of the pathogens.",59:"Chemical profiling of a ginger extract and tests of its activity against Ralstonia solanacearum.",60:"Isolation and characterisation of endophytic bacteria from ginger rhizome.",61:"Controlled experiment on waterlogging and high temperature and the photosynthesis of ginger.",64:"Hormone and transcriptome profiling of ginger rhizome at three stages of enlargement.",66:"In vitro test of ginger essential oil against Phytophthora colocasiae, the cause of taro leaf blight.",67:"Part 1 of a monograph reviewing ginger's production, processing and flavour chemistry.",68:"Part 2 of the same monograph, on the evaluation of ginger quality.",72:"Comparison of flavour compounds in fresh and dried Australian-grown ginger extracted with supercritical carbon dioxide.",73:"Study of how sun, solar-tunnel and hot-air drying affect gingerol and shogaol content of ginger.",74:"First characterisation of the ginger protease, named zingibain, and its action on meat proteins.",75:"Review of the composition, extraction, pungency and bioactivity of gingerols and related compounds.",80:"Analysis of plant microremains on grinding stones from Oc Eo, Vietnam, identifying eight spices including ginger.",83:"Historical study of three medieval pharmacology texts on why Asian spices were valued as medicines in Europe.",85:"Historical account of the 1930–31 Jamaica ginger paralysis epidemic and the investigation into its cause.",86:"Clinical follow-up of 11 survivors of the 1930 Jamaica ginger poisoning, 47 years on.",87:"Quantitative analysis of spice use in 4578 recipes from 36 countries, testing the antimicrobial hypothesis.",88:"Summary article on the antimicrobial hypothesis of spice use and its alternatives.",89:"Review of ginger preparations in traditional Chinese medicine and their distinct attributed uses.",91:"Experiment on supplementary green light and the photosynthesis of ginger.",92:"Study of combined high-temperature and intense-light stress in ginger.",93:"Expressed-sequence-tag study of eight ginger and turmeric tissues, with a proposed gingerol and curcuminoid pathway.",94:"State agriculture department fact sheet on ginger wilt after its first detection in Minnesota in 2023.",95:"Public summary of the European regulator's conclusions on the medicinal uses of ginger rhizome.",96:"Museum label on ginger and sugar in European food and medicine, 1500–1800.",97:"Catalogue record of the ginger illustration in a tenth-century Byzantine copy of Dioscorides.",98:"Entry on ginger in a medieval Irish materia medica, in an edited English translation.",99:"English royal cookery roll of about 1390, in Samuel Pegge's 1780 edition.",100:"Editor's foreword to an edition of two fifteenth-century English cookery manuscripts.",101:"Botanical profile of ginger from Oxford University Herbaria."}
t=open(C+"review.md",encoding="utf-8").read()
order=[]
for m in re.finditer(r"\[(\d+(?:, \d+)*)\]",t):
    for x in m.group(1).split(", "):
        if int(x) not in order: order.append(int(x))
new={o:i+1 for i,o in enumerate(order)}
ren=lambda s: re.sub(r"\[(\d+(?:, \d+)*)\]",lambda m:"["+", ".join(str(v) for v in sorted(new[int(x)] for x in m.group(1).split(", ")))+"]",s)
secs={}; cur=None
for line in t.split("\n"):
    m=re.match(r"<!-- section: ([\w-]+) -->",line)
    if m: cur=m.group(1)
    for mm in re.finditer(r"\[(\d+(?:, \d+)*)\]",line):
        for x in mm.group(1).split(", "): secs.setdefault(int(x),[]); (cur in secs[int(x)]) or secs[int(x)].append(cur)
open(C+"review.md","w",encoding="utf-8").write(ren(t))
rc=open(C+"recipes.yaml",encoding="utf-8").read(); rc=ren(rc); rc=re.sub(r"source_ref: (\d+)",lambda m:f"source_ref: {new[int(m.group(1))]}",rc); open(C+"recipes.yaml","w",encoding="utf-8").write(rc)
out=[]
for o in order:
    r=by[o]; fa=r["first_author"]; yr=r["year"]
    cit=f'{fa}{" et al." if r.get("doi") and "Agency" not in fa else ""}. {r["title"]}. {r.get("venue") or ""}{". "+str(yr) if yr else ""}.'
    tier=r["tier"]
    e={"n":new[o],"tier":tier,"anchor":bool(r.get("anchor")),"citation":cit,"year":yr or 2026,"summary":S[o],"role_here":"evidence","role_note":"Cited in: "+", ".join(secs[o]),"cited_in":secs[o],"verified":True,"verified_level":r.get("verified_level","abstract"),"candidate_n":o}
    if r.get("doi"): e["doi"]=r["doi"]
    if not r.get("doi") and r.get("venue"): e["url"]=("https://"+r["venue"]) if "." in r["venue"] and " " not in r["venue"] else None
    if tier=="seminal": e["why_it_mattered"]="See role note; to be expanded when the full text is read."
    out.append({k:v for k,v in e.items() if v is not None})
yaml.safe_dump(out,open(C+"references.yaml","w",encoding="utf-8"),sort_keys=False,allow_unicode=True,width=220)
json.dump(new,open("source/sweep/renumber-map.json","w"))
print(len(out),"references; first cited:",order[:8])
